class Termination:
    def __or__(self, other):
        return _AnyOf(self, other)


class _AnyOf(Termination):
    def __init__(self, *conditions):
        self.conditions = conditions

    def __call__(self, transcript):
        return any(condition(transcript) for condition in self.conditions)


class TextMention(Termination):
    def __init__(self, token):
        self.token = token

    def __call__(self, transcript):
        return bool(transcript) and self.token in transcript[-1]["content"]


class MaxMessages(Termination):
    def __init__(self, limit):
        self.limit = limit

    def __call__(self, transcript):
        return len(transcript) >= self.limit


def round_robin(agents, transcript):
    turns = len(transcript) - 1
    return agents[turns % len(agents)]


def run_chat(agents, opening, select, terminate, max_turns=10):
    if not agents:
        raise ValueError("a conversation needs at least one agent")
    transcript = [{"name": "user", "content": opening}]
    for _ in range(max_turns):
        speaker = select(agents, transcript)
        reply = speaker["reply"](transcript)
        transcript.append({"name": speaker["name"], "content": reply})
        if terminate(transcript):
            break
    return transcript
